-- ===========================================================================
-- NyaySetu :: upgrade_2_0.sql
--
-- Upgrades a database that already has migrations 001–007 to NyaySetu 2.0.
-- It is migrations 008 to 013, in order, in one file. Generated by
-- scripts/bundle-upgrade.mjs — edit the migrations, not this file.
--
-- HOW TO RUN
--   1. Supabase dashboard → Database → Backups: confirm a recent backup exists.
--   2. SQL Editor → New query → paste this whole file → Run.
--   3. Check: open <your API>/api/health and confirm
--      subsystems.database.schema.upToDate is true.
--
-- SAFETY
--   Additive only: creates tables, columns, functions, policies and triggers.
--   Nothing is dropped and no existing row is deleted. Idempotent: running it
--   twice changes nothing the second time.
-- ===========================================================================


-- ###########################################################################
-- 008_case_intake.sql
-- ###########################################################################

-- ===========================================================================
-- NyaySetu :: 008_case_intake.sql            (2.0 · F1 case intake)
-- Run after 007_account_removal.sql.
--
-- WHAT CHANGES
--   1. Every case gets a case_reference of its own (NS/<STATION>/<YEAR>/<SERIAL>).
--      It is what a case is called everywhere: screens, documents, the public
--      verification page. The FIR is no longer the case's identity.
--   2. The FIR moves into fir_records, one optional row per case, unique per
--      (police station, year, FIR number) — which is how FIRs are actually numbered.
--      fir_records is readable only by police, prosecutor, judge and court admin.
--   3. New cases are keyed on chain by a salted hash (case_key_scheme = salted_v2),
--      so neither the FIR nor the case reference can be recovered from the chain.
--      Cases created before 2.0 keep keccak256(FIR): their anchors are already on
--      chain and cannot be re-keyed. See docs/DECISIONS.md D-02.
--   4. The light theme becomes the default (D-11).
--
-- WHAT DOES NOT CHANGE
--   cases.fir_number stays, with its data and its unique constraint. It is made
--   nullable so a 2.0 case need not have one, and it is left untouched for every
--   existing row. The API stops returning it to roles that may not see FIRs.
--
-- Idempotent: safe to run twice.
-- ===========================================================================

-- ------------------------------------------------------------------ theme

alter table public.users alter column theme set default 'light';
-- One-time reset: the old default was 'dark' and a stored 'dark' cannot be told
-- apart from a deliberate choice. Guarded so a re-run does not undo later choices.
do $$
begin
  if not exists (select 1 from pg_class where relname = 'cases_case_reference_key') then
    update public.users set theme = 'light' where theme = 'dark';
  end if;
end $$;

-- ------------------------------------------------------------------ cases

alter table public.cases
  add column if not exists case_reference text,
  add column if not exists case_key_scheme text not null default 'fir_v1',
  add column if not exists case_salt text,
  add column if not exists origin text not null default 'fir';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'cases_case_key_scheme_check') then
    alter table public.cases add constraint cases_case_key_scheme_check
      check (case_key_scheme in ('fir_v1', 'salted_v2'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'cases_origin_check') then
    alter table public.cases add constraint cases_origin_check
      check (origin in ('fir', 'complaint', 'court', 'other'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'cases_case_salt_check') then
    alter table public.cases add constraint cases_case_salt_check
      check (case_salt is null or case_salt ~ '^[0-9a-f]{64}$');
  end if;
  -- A salted key without its salt could never be re-derived, and a 1.0 key with
  -- one would be a lie about how it was made.
  if not exists (select 1 from pg_constraint where conname = 'cases_salt_matches_scheme') then
    alter table public.cases add constraint cases_salt_matches_scheme
      check ((case_key_scheme = 'salted_v2') = (case_salt is not null));
  end if;
end $$;

-- A 2.0 case may have no FIR at all (a complaint under inquiry, a court matter).
alter table public.cases alter column fir_number drop not null;

-- Back-fill a reference for every case that predates this migration. The FIR
-- number was unique, so the reference is too.
update public.cases
   set case_reference = 'NS/FIR/' || left(upper(regexp_replace(fir_number, '[^A-Za-z0-9/_-]+', '-', 'g')), 80)
 where case_reference is null and fir_number is not null;

update public.cases
   set case_reference = 'NS/CASE/' || upper(substr(replace(id::text, '-', ''), 1, 12))
 where case_reference is null;

alter table public.cases alter column case_reference set not null;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'cases_case_reference_key') then
    alter table public.cases add constraint cases_case_reference_key unique (case_reference);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'cases_case_reference_format') then
    alter table public.cases add constraint cases_case_reference_format
      check (case_reference ~ '^NS/[A-Z0-9/_-]{3,90}$');
  end if;
end $$;

comment on column public.cases.case_reference is
  'The case''s own identity. Shown everywhere a case is named; never derived from the FIR for 2.0 cases.';
comment on column public.cases.case_salt is
  '32 random bytes (hex). case_id_hash = keccak256("nyaysetu:case:v2:" || case_reference || ":" || case_salt) for salted_v2.';
comment on column public.cases.fir_number is
  '1.0 only. Kept for the cases that were keyed by it. 2.0 cases leave it null and use fir_records.';

-- Serial numbers per station and year, handed out atomically.
create table if not exists public.case_reference_counters (
  station_code text not null,
  year         integer not null check (year between 1950 and 2200),
  last_serial  integer not null default 0 check (last_serial >= 0),
  updated_at   timestamptz not null default now(),
  primary key (station_code, year)
);
comment on table public.case_reference_counters is '2.0: serial counters for case references. Service-only.';

create or replace function public.next_case_reference(p_station_code text, p_year integer)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_serial integer;
  v_code   text := upper(regexp_replace(coalesce(p_station_code, ''), '[^A-Za-z0-9]+', '-', 'g'));
begin
  v_code := trim(both '-' from v_code);
  if v_code = '' then
    raise exception 'A station or court code is required to number a case.';
  end if;
  v_code := left(v_code, 40);

  insert into public.case_reference_counters as c (station_code, year, last_serial)
  values (v_code, p_year, 1)
  on conflict (station_code, year)
  do update set last_serial = c.last_serial + 1, updated_at = now()
  returning last_serial into v_serial;

  return 'NS/' || v_code || '/' || p_year::text || '/' || lpad(v_serial::text, 6, '0');
end;
$$;

revoke all on function public.next_case_reference(text, integer) from public, anon, authenticated;
grant execute on function public.next_case_reference(text, integer) to service_role;

-- ------------------------------------------------------------- FIR records

create table if not exists public.fir_records (
  id                  uuid primary key default gen_random_uuid(),
  case_id             uuid not null unique references public.cases (id) on delete restrict,
  fir_number          text not null check (char_length(fir_number) between 1 and 40),
  fir_number_norm     text not null,
  fir_year            integer not null check (fir_year between 1950 and 2200),
  fir_date            date,
  police_station      text not null check (char_length(police_station) between 2 and 160),
  police_station_norm text not null,
  district            text,
  -- True for rows copied from cases.fir_number by this migration, whose year was
  -- inferred from the registration date rather than entered.
  backfilled          boolean not null default false,
  recorded_by         uuid references public.users (id),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint fir_records_date_matches_year
    check (fir_date is null or extract(year from fir_date)::integer = fir_year)
);

create unique index if not exists fir_records_station_year_number_key
  on public.fir_records (police_station_norm, fir_year, fir_number_norm);

comment on table public.fir_records is
  '2.0: the FIR linked to a case, if any. Never on chain; readable by police, prosecutor, judge and court admin only.';

insert into public.fir_records (
  case_id, fir_number, fir_number_norm, fir_year, police_station, police_station_norm, backfilled, recorded_by
)
select c.id,
       c.fir_number,
       upper(regexp_replace(c.fir_number, '\s+', '', 'g')),
       extract(year from c.registered_at)::integer,
       c.police_station,
       lower(regexp_replace(c.police_station, '[^A-Za-z0-9]+', '-', 'g')),
       true,
       c.registered_by
  from public.cases c
 where c.fir_number is not null
   and not exists (select 1 from public.fir_records f where f.case_id = c.id)
on conflict do nothing;

-- ---------------------------------------------------------------- security

alter table public.case_reference_counters enable row level security;
alter table public.fir_records enable row level security;

revoke all on public.case_reference_counters from anon, authenticated;

drop policy if exists fir_records_read on public.fir_records;
create policy fir_records_read on public.fir_records
  for select to authenticated
  using (
    app.has_role(array['court_admin'])
    or (app.has_role(array['police', 'prosecutor', 'judge']) and app.is_assigned(case_id))
  );

drop policy if exists fir_records_write on public.fir_records;
create policy fir_records_write on public.fir_records
  for all to authenticated
  using (app.has_role(array['court_admin']) or (app.has_role(array['police']) and app.can_write_case(case_id)))
  with check (app.has_role(array['court_admin']) or (app.has_role(array['police']) and app.can_write_case(case_id)));

-- --------------------------------------------------------------- triggers

drop trigger if exists touch_updated_at on public.fir_records;
create trigger touch_updated_at before update on public.fir_records
  for each row execute function app.touch_updated_at();

drop trigger if exists audit_changes on public.fir_records;
create trigger audit_changes after insert or update or delete on public.fir_records
  for each row execute function app.audit_trigger();

drop trigger if exists audit_changes on public.case_reference_counters;
create trigger audit_changes after insert or update or delete on public.case_reference_counters
  for each row execute function app.audit_trigger();

comment on table public.case_reference_counters is '2.0: serial counters for case references. Service-only.';

create index if not exists cases_reference_idx on public.cases (case_reference);
create index if not exists action_log_case_time_idx on public.action_log (case_id, occurred_at);

do $$ begin raise notice 'Migration 008 complete: case references, FIR records, light theme default.'; end $$;


-- ###########################################################################
-- 009_verification_state.sql
-- ###########################################################################

-- ===========================================================================
-- NyaySetu :: 009_verification_state.sql     (2.0 · F2 verification state)
-- Run after 008_case_intake.sql.
--
-- Every chain write that concerns evidence becomes an ANCHOR: a row that says
-- what was meant to be written (contract, method, the digest, the event that
-- should come back) and how far it has got.
--
--   LOCAL_ONLY → SUBMITTED → CONFIRMED
--   plus INTEGRITY_MISMATCH, SYNC_ERROR, REVIEW_REQUIRED
--
-- These are APPLICATION states, not contract states. The contract knows nothing
-- about them. CONFIRMED means: the receipt succeeded, the expected event was
-- decoded from it with the expected digest and case, and enough blocks sit on
-- top. The transition table lives in exactly one place,
-- backend/src/services/verification/stateMachine.ts, and every transition is
-- appended to anchor_state_events, which cannot be edited.
--
-- Idempotent.
-- ===========================================================================

do $$ begin
  create type public.verification_state as enum (
    'LOCAL_ONLY', 'SUBMITTED', 'CONFIRMED', 'INTEGRITY_MISMATCH', 'SYNC_ERROR', 'REVIEW_REQUIRED'
  );
exception when duplicate_object then null; end $$;

create table if not exists public.anchors (
  id                     uuid primary key default gen_random_uuid(),
  purpose                text not null check (purpose in (
                           'evidence_registration', 'custody_transfer', 'integrity_check',
                           'forensic_report', 'anomaly_flag', 'document')),
  contract               text not null check (contract in ('EvidenceChain', 'SummonsChain', 'BailChain')),
  method                 text not null,
  -- The arguments as sent, JSON with bigints as decimal strings, so a retry
  -- sends exactly what the first attempt would have.
  args                   jsonb not null default '[]'::jsonb,
  case_id                uuid references public.cases (id) on delete restrict,
  subject_type           text not null,
  subject_id             text not null,
  parent_anchor_id       uuid references public.anchors (id) on delete restrict,
  -- One event name, or alternatives separated by "|" (an integrity check emits
  -- either IntegrityVerified or IntegrityMismatch, and both are a successful record).
  expected_event         text not null,
  expected_digest        public.hash32 not null,
  -- Which event argument carries the digest ("fileHash", "checkHash|submittedHash").
  digest_arg             text not null default 'fileHash',
  -- Other event arguments that must match, e.g. {"caseId": "0x…"} or {"evidenceId": "12"}.
  expected_args          jsonb not null default '{}'::jsonb,
  -- The id the contract assigned (evidenceId), once decoded from the event.
  chain_record_id        bigint,
  state                  public.verification_state not null default 'LOCAL_ONLY',
  tx_hash                public.tx_hash,
  block_number           bigint,
  block_hash             text check (block_hash is null or block_hash ~ '^0x[0-9a-f]{64}$'),
  confirmations          integer not null default 0 check (confirmations >= 0),
  required_confirmations integer not null default 1 check (required_confirmations >= 1),
  attempts               integer not null default 0 check (attempts >= 0),
  submitted_at           timestamptz,
  confirmed_at           timestamptz,
  last_checked_at        timestamptz,
  failure_code           text,
  failure_reason         text,
  idempotency_key        text unique check (idempotency_key is null or char_length(idempotency_key) between 8 and 200),
  created_by             uuid references public.users (id) on delete set null,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  constraint anchors_confirmed_has_proof
    check (state <> 'CONFIRMED' or (tx_hash is not null and block_number is not null and block_hash is not null))
);

comment on table public.anchors is
  '2.0: every evidence-related chain write and how far it has got. Application state, not contract state.';

create index if not exists anchors_state_idx on public.anchors (state, updated_at);
create index if not exists anchors_case_idx on public.anchors (case_id, created_at);
create index if not exists anchors_subject_idx on public.anchors (subject_type, subject_id);
create index if not exists anchors_tx_idx on public.anchors (tx_hash);

create table if not exists public.anchor_state_events (
  id          bigserial primary key,
  anchor_id   uuid not null references public.anchors (id) on delete restrict,
  from_state  public.verification_state,
  to_state    public.verification_state not null,
  reason_code text not null,
  reason      text,
  actor_id    uuid references public.users (id) on delete set null,
  actor_role  text,
  occurred_at timestamptz not null default now()
);

comment on table public.anchor_state_events is
  '2.0: append-only history of every verification state transition.';

create index if not exists anchor_state_events_anchor_idx on public.anchor_state_events (anchor_id, occurred_at);

-- Append-only, enforced in the database: history that can be edited is not history.
create or replace function app.refuse_mutation()
returns trigger
language plpgsql
as $$
begin
  raise exception '% is append-only: % refused', tg_table_name, tg_op;
end;
$$;

drop trigger if exists append_only on public.anchor_state_events;
create trigger append_only before update or delete on public.anchor_state_events
  for each row execute function app.refuse_mutation();

-- ------------------------------------------------------- evidence linkage

alter table public.evidence_items
  add column if not exists anchor_id uuid references public.anchors (id) on delete restrict,
  add column if not exists idempotency_key text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'evidence_items_idempotency_key_key') then
    alter table public.evidence_items add constraint evidence_items_idempotency_key_key unique (idempotency_key);
  end if;
end $$;

create index if not exists evidence_anchor_idx on public.evidence_items (anchor_id);

-- Back-fill an anchor for every item registered before 2.0. One with a
-- registration transaction starts as SUBMITTED, and the tracker confirms it
-- the normal way — by fetching the receipt and decoding the event — rather than
-- this migration declaring it confirmed. One with no transaction is a SYNC_ERROR:
-- its registration never reached the chain.
do $$
declare
  e record;
  v_anchor uuid;
begin
  for e in
    select ei.id, ei.case_id, ei.file_hash, ei.registration_tx_hash, ei.chain_evidence_id, ei.officer_id, ei.created_at
      from public.evidence_items ei
     where ei.anchor_id is null
  loop
    insert into public.anchors (
      purpose, contract, method, case_id, subject_type, subject_id, expected_event, expected_digest,
      chain_record_id, state, tx_hash, submitted_at, failure_code, failure_reason,
      idempotency_key, created_by, created_at
    ) values (
      'evidence_registration', 'EvidenceChain', 'registerEvidence', e.case_id, 'evidence_item', e.id::text,
      'EvidenceRegistered', e.file_hash, e.chain_evidence_id,
      case when e.registration_tx_hash is not null then 'SUBMITTED' else 'SYNC_ERROR' end::public.verification_state,
      e.registration_tx_hash,
      case when e.registration_tx_hash is not null then e.created_at end,
      case when e.registration_tx_hash is null then 'NEVER_ANCHORED' end,
      case when e.registration_tx_hash is null then 'Registered before 2.0 without a registration transaction.' end,
      'evidence:' || e.id::text || ':registration', e.officer_id, e.created_at
    )
    returning id into v_anchor;

    insert into public.anchor_state_events (anchor_id, from_state, to_state, reason_code, reason)
    values (
      v_anchor, null,
      case when e.registration_tx_hash is not null then 'SUBMITTED' else 'SYNC_ERROR' end::public.verification_state,
      'BACKFILL_2_0', 'State assigned when 2.0 was installed; confirmation is re-derived from the chain.'
    );

    update public.evidence_items set anchor_id = v_anchor where id = e.id;
  end loop;
end $$;

-- ---------------------------------------------------------------- security

alter table public.anchors enable row level security;
alter table public.anchor_state_events enable row level security;

drop policy if exists anchors_read on public.anchors;
create policy anchors_read on public.anchors
  for select to authenticated
  using (app.has_role(array['court_admin']) or (case_id is not null and app.is_assigned(case_id)));

drop policy if exists anchor_state_events_read on public.anchor_state_events;
create policy anchor_state_events_read on public.anchor_state_events
  for select to authenticated
  using (
    exists (
      select 1 from public.anchors a
       where a.id = anchor_state_events.anchor_id
         and (app.has_role(array['court_admin']) or (a.case_id is not null and app.is_assigned(a.case_id)))
    )
  );

-- Written only by the API.
revoke insert, update, delete on public.anchors from anon, authenticated;
revoke insert, update, delete on public.anchor_state_events from anon, authenticated;

drop trigger if exists touch_updated_at on public.anchors;
create trigger touch_updated_at before update on public.anchors
  for each row execute function app.touch_updated_at();

drop trigger if exists audit_changes on public.anchors;
create trigger audit_changes after insert or update or delete on public.anchors
  for each row execute function app.audit_trigger();

drop trigger if exists audit_changes on public.anchor_state_events;
create trigger audit_changes after insert on public.anchor_state_events
  for each row execute function app.audit_trigger();

do $$ begin raise notice 'Migration 009 complete: verification state machine.'; end $$;


-- ###########################################################################
-- 010_passport_capture.sql
-- ###########################################################################

-- ===========================================================================
-- NyaySetu :: 010_passport_capture.sql   (2.0 · F3 passport, F10/F12 capture)
-- Run after 009_verification_state.sql.
--
-- F3  Every item gets an unguessable public reference for its Integrity
--     Passport: a page anyone can open, which shows only the reference, the
--     anchored digest, the transaction, block time, verification state and the
--     custody event types with role labels. Nothing personal.
--
-- F10 Live capture. For a capture, the value anchored on chain is the SHA-256 of
--     a canonical manifest that contains the file's digest, the GPS fix, the
--     device time and the device (docs/DECISIONS.md D-04). anchored_digest is
--     whatever went on chain; file_hash stays the file's own digest.
--
--     The manifest holds raw coordinates, so it is readable only by roles
--     assigned to the case, and never appears on the public page, which says only
--     "location committed in anchor".
--
-- Idempotent.
-- ===========================================================================

alter table public.evidence_items
  add column if not exists public_ref text,
  add column if not exists source text not null default 'upload',
  add column if not exists anchor_mode text not null default 'file',
  add column if not exists anchored_digest public.hash32,
  add column if not exists capture_purpose text not null default 'general',
  add column if not exists capture_manifest jsonb,
  add column if not exists manifest_hash public.hash32,
  add column if not exists manifest_signature jsonb,
  add column if not exists signature_status text not null default 'none',
  add column if not exists gps_status text,
  add column if not exists gps_accuracy_m numeric(10, 2) check (gps_accuracy_m is null or gps_accuracy_m >= 0),
  add column if not exists gps_mocked boolean,
  add column if not exists device_id text,
  add column if not exists app_version text,
  add column if not exists device_time timestamptz,
  add column if not exists server_received_at timestamptz,
  add column if not exists clock_skew_seconds integer,
  add column if not exists clock_skew_flagged boolean not null default false,
  add column if not exists duration_ms integer check (duration_ms is null or duration_ms >= 0);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'evidence_items_source_check') then
    alter table public.evidence_items add constraint evidence_items_source_check
      check (source in ('upload', 'capture'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'evidence_items_anchor_mode_check') then
    alter table public.evidence_items add constraint evidence_items_anchor_mode_check
      check (anchor_mode in ('file', 'manifest'));
  end if;
  -- A manifest-anchored item must carry the manifest and its digest, or it could
  -- never be verified.
  if not exists (select 1 from pg_constraint where conname = 'evidence_items_manifest_complete') then
    alter table public.evidence_items add constraint evidence_items_manifest_complete
      check (anchor_mode <> 'manifest' or (capture_manifest is not null and manifest_hash is not null));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'evidence_items_capture_purpose_check') then
    alter table public.evidence_items add constraint evidence_items_capture_purpose_check
      check (capture_purpose in ('general', 'search_seizure', 'lab_intake'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'evidence_items_signature_status_check') then
    alter table public.evidence_items add constraint evidence_items_signature_status_check
      check (signature_status in ('none', 'valid', 'invalid', 'unknown_key'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'evidence_items_gps_status_check') then
    alter table public.evidence_items add constraint evidence_items_gps_status_check
      check (gps_status is null or gps_status in ('OK', 'LOW_ACCURACY', 'NO_GPS'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'evidence_items_public_ref_format') then
    alter table public.evidence_items add constraint evidence_items_public_ref_format
      check (public_ref is null or public_ref ~ '^NSE-[0-9A-Z]{26,32}$');
  end if;
end $$;

-- References for items that predate 2.0: 122 random bits from a v4 UUID.
update public.evidence_items
   set public_ref = 'NSE-' || upper(replace(gen_random_uuid()::text, '-', ''))
 where public_ref is null;

update public.evidence_items set anchored_digest = file_hash where anchored_digest is null;

alter table public.evidence_items alter column public_ref set not null;
alter table public.evidence_items alter column anchored_digest set not null;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'evidence_items_public_ref_key') then
    alter table public.evidence_items add constraint evidence_items_public_ref_key unique (public_ref);
  end if;
end $$;

comment on column public.evidence_items.public_ref is
  'Unguessable reference for the public Integrity Passport. Reveals nothing about the case.';
comment on column public.evidence_items.anchored_digest is
  'The digest written on chain: the file''s SHA-256 for uploads, the manifest''s SHA-256 for live captures.';
comment on column public.evidence_items.capture_manifest is
  'Canonical capture manifest (contains raw coordinates). Assigned case roles only; never public.';

-- --------------------------------------------------------- device keys

-- A device that signs its capture manifests registers its key here once. The
-- web app holds a non-extractable ECDSA P-256 key and registers the public half;
-- the phone holds an HMAC secret in its secure store and registers it, encrypted
-- at rest with the evidence key. A valid signature shows a manifest came from a
-- registered install of the app; it is not hardware attestation.
create table if not exists public.device_keys (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references public.users (id) on delete cascade,
  key_id           text not null unique check (key_id ~ '^[A-Za-z0-9_-]{8,80}$'),
  algorithm        text not null check (algorithm in ('ECDSA-P256-SHA256', 'HMAC-SHA256')),
  public_jwk       jsonb,
  secret_encrypted text,
  platform         text not null check (platform in ('web', 'android', 'ios')),
  label            text,
  created_at       timestamptz not null default now(),
  revoked_at       timestamptz,
  constraint device_keys_material check (
    (algorithm = 'ECDSA-P256-SHA256' and public_jwk is not null and secret_encrypted is null)
    or (algorithm = 'HMAC-SHA256' and secret_encrypted is not null and public_jwk is null)
  )
);

comment on table public.device_keys is
  '2.0: capture-manifest signing keys, one per app install. Public keys and encrypted HMAC secrets only.';

create index if not exists device_keys_user_idx on public.device_keys (user_id) where revoked_at is null;

alter table public.device_keys enable row level security;

drop policy if exists device_keys_self_read on public.device_keys;
create policy device_keys_self_read on public.device_keys
  for select to authenticated
  using (user_id = app.current_user_id() or app.has_role(array['court_admin']));

revoke insert, update, delete on public.device_keys from anon, authenticated;

drop trigger if exists audit_changes on public.device_keys;
create trigger audit_changes after insert or update or delete on public.device_keys
  for each row execute function app.audit_trigger();

do $$ begin raise notice 'Migration 010 complete: integrity passport and capture manifests.'; end $$;


-- ###########################################################################
-- 011_chunked_uploads.sql
-- ###########################################################################

-- ===========================================================================
-- NyaySetu :: 011_chunked_uploads.sql    (2.0 · F12 search and seizure video)
-- Run after 010_passport_capture.sql.
--
-- A search can run for most of an hour, and a recording of it is hundreds of
-- megabytes sent from a phone on a field connection. Sent as one request, a
-- dropped connection at 90% loses everything. So a recording is sent in pieces:
-- each piece is checked against its own SHA-256 when it arrives, stored
-- encrypted, and the upload can resume from the first missing piece. Only when
-- every piece is present is the whole recording reassembled, its full SHA-256
-- recomputed, and the item registered.
--
-- Witness names for a search-and-seizure recording live in
-- evidence_items.witnesses: off chain, never on the public page, never returned
-- to the accused.
--
-- Idempotent.
-- ===========================================================================

create table if not exists public.upload_sessions (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references public.users (id) on delete cascade,
  case_id         uuid not null references public.cases (id) on delete cascade,
  file_name       text not null check (char_length(file_name) between 1 and 255),
  mime_type       text not null,
  total_bytes     bigint not null check (total_bytes > 0),
  chunk_size      integer not null check (chunk_size between 262144 and 16777216),
  total_chunks    integer not null check (total_chunks > 0),
  -- The whole recording's SHA-256 as the device computed it. Checked again at
  -- assembly against what actually arrived.
  declared_sha256 public.hash32 not null,
  -- Indexes received so far, and each piece's digest, so a re-sent piece with the
  -- same bytes is accepted and one with different bytes is refused.
  received        integer[] not null default '{}',
  chunk_digests   jsonb not null default '{}'::jsonb,
  status          text not null default 'open' check (status in ('open', 'consumed', 'expired', 'refused')),
  evidence_id     uuid references public.evidence_items (id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  expires_at      timestamptz not null default (now() + interval '48 hours')
);

comment on table public.upload_sessions is
  '2.0: resumable uploads of long recordings. Pieces are stored encrypted until assembled.';

create index if not exists upload_sessions_user_idx on public.upload_sessions (user_id, created_at desc);
create index if not exists upload_sessions_open_idx on public.upload_sessions (expires_at) where status = 'open';

alter table public.evidence_items
  add column if not exists witnesses jsonb,
  add column if not exists search_checklist jsonb;

comment on column public.evidence_items.witnesses is
  'Search and seizure: witnesses present, as [{name, description}]. Off chain; never public; never to the accused.';

alter table public.upload_sessions enable row level security;

drop policy if exists upload_sessions_own on public.upload_sessions;
create policy upload_sessions_own on public.upload_sessions
  for select to authenticated
  using (user_id = app.current_user_id() or app.has_role(array['court_admin']));

revoke insert, update, delete on public.upload_sessions from anon, authenticated;

drop trigger if exists touch_updated_at on public.upload_sessions;
create trigger touch_updated_at before update on public.upload_sessions
  for each row execute function app.touch_updated_at();

drop trigger if exists audit_changes on public.upload_sessions;
create trigger audit_changes after insert or update or delete on public.upload_sessions
  for each row execute function app.audit_trigger();

do $$ begin raise notice 'Migration 011 complete: resumable uploads for long recordings.'; end $$;


-- ###########################################################################
-- 012_workflows.sql
-- ###########################################################################

-- ===========================================================================
-- NyaySetu :: 012_workflows.sql
-- Run after 011_chunked_uploads.sql.
--
-- The role workflows of 2.0, in one migration because they reference each
-- other (a disposal needs an approval; a lab re-check raises an alert):
--
--   F11  document_templates, certificates            Section 63 certificate
--   F13  seizures, seizure_items, malkhana_movements Police workflow
--   F14  lab_intakes, working_copies, report versions Forensic laboratory
--   F16  access_requests, objections                  Defence
--   F17  court_events, summons_service_attempts       Court
--   F18  checkin_explanations, notification_outbox    Accused / witness
--   F19  approval_requests, legal_holds, disposal_records  Governance
--   F4   discrepancy_alerts, alert_comments           Audit trail and alerts
--   F5   ai_reviews                                   Human review of AI output
--
-- Every table: RLS on (default-deny), reads limited to the case's assigned roles
-- or the registry, writes only through the API, audit trigger attached.
-- Idempotent.
-- ===========================================================================

-- ------------------------------------------------------------- F11 templates

create table if not exists public.document_templates (
  id            uuid primary key default gen_random_uuid(),
  template_key  text not null unique check (template_key ~ '^[a-z0-9_]{3,60}$'),
  title         text not null,
  -- Ordered sections: [{heading, body}]. Bodies may contain {placeholders}.
  sections      jsonb not null,
  footer        text not null,
  version       integer not null default 1 check (version >= 1),
  updated_by    uuid references public.users (id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
comment on table public.document_templates is
  '2.0: editable document templates (Section 63 certificate, seizure memo, custody form). Templates, not legal advice.';

create table if not exists public.certificates (
  id                uuid primary key default gen_random_uuid(),
  evidence_id       uuid not null references public.evidence_items (id) on delete restrict,
  case_id           uuid not null references public.cases (id) on delete restrict,
  template_key      text not null,
  template_version  integer not null,
  pdf_sha256        public.hash32 not null,
  anchored_digest   public.hash32 not null,
  fields            jsonb not null,
  generated_by      uuid references public.users (id) on delete set null,
  generated_role    text,
  generated_at      timestamptz not null default now()
);
comment on table public.certificates is '2.0: every Section 63 certificate rendering, by digest.';
create index if not exists certificates_evidence_idx on public.certificates (evidence_id, generated_at desc);

-- ------------------------------------------------------------- F13 police

create table if not exists public.seizures (
  id               uuid primary key default gen_random_uuid(),
  case_id          uuid not null references public.cases (id) on delete restrict,
  memo_number      text not null,
  memo_digest      public.hash32,
  seized_at        timestamptz not null,
  -- Off chain, role-gated: where and from whom.
  place            text not null,
  seized_from      text,
  witnesses        jsonb not null default '[]'::jsonb,
  notes            text,
  created_by       uuid references public.users (id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (case_id, memo_number)
);
comment on table public.seizures is '2.0: a seizure memo grouping related items (phone, SIM, memory card).';

create table if not exists public.seizure_items (
  id           uuid primary key default gen_random_uuid(),
  seizure_id   uuid not null references public.seizures (id) on delete cascade,
  evidence_id  uuid not null unique references public.evidence_items (id) on delete restrict,
  item_label   text not null,
  description  text,
  item_index   integer not null check (item_index >= 1),
  created_at   timestamptz not null default now(),
  unique (seizure_id, item_index)
);
comment on table public.seizure_items is '2.0: each item of a seizure, with its own evidence record and digest.';

create table if not exists public.malkhana_movements (
  id            uuid primary key default gen_random_uuid(),
  evidence_id   uuid not null references public.evidence_items (id) on delete restrict,
  case_id       uuid not null references public.cases (id) on delete restrict,
  movement      text not null check (movement in ('IN', 'OUT', 'RETURN', 'TRANSFER')),
  location      text not null,
  shelf         text,
  reason        text not null,
  counterparty  text,
  performed_by  uuid references public.users (id) on delete set null,
  occurred_at   timestamptz not null default now(),
  -- The movement's canonical digest, anchored like a custody transfer (D-06).
  movement_digest public.hash32 not null,
  anchor_id     uuid references public.anchors (id) on delete set null,
  created_at    timestamptz not null default now()
);
comment on table public.malkhana_movements is '2.0: the malkhana (property room) register. Append-only.';
create index if not exists malkhana_evidence_idx on public.malkhana_movements (evidence_id, occurred_at);

drop trigger if exists append_only on public.malkhana_movements;
create trigger append_only before update or delete on public.malkhana_movements
  for each row execute function app.refuse_mutation();

-- ------------------------------------------------------------- F14 laboratory

create table if not exists public.lab_intakes (
  id                     uuid primary key default gen_random_uuid(),
  evidence_id            uuid not null references public.evidence_items (id) on delete restrict,
  case_id                uuid not null references public.cases (id) on delete restrict,
  seal_intact            boolean not null,
  seal_notes             text,
  packaging_evidence_ids uuid[] not null default '{}',
  received_by            uuid references public.users (id) on delete set null,
  received_at            timestamptz not null default now(),
  condition_notes        text,
  recheck_digest         public.hash32,
  recheck_matched        boolean,
  recheck_anchor_id      uuid references public.anchors (id) on delete set null,
  status                 text not null default 'received' check (status in ('received', 'in_analysis', 'reported', 'returned')),
  status_changed_at      timestamptz not null default now(),
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now()
);
comment on table public.lab_intakes is '2.0: laboratory intake checklist and the hash re-check on arrival.';
create index if not exists lab_intakes_case_idx on public.lab_intakes (case_id, received_at);

create table if not exists public.working_copies (
  id                    uuid primary key default gen_random_uuid(),
  original_evidence_id  uuid not null references public.evidence_items (id) on delete restrict,
  case_id               uuid not null references public.cases (id) on delete restrict,
  copy_sha256           public.hash32 not null,
  tool                  text not null,
  tool_version          text not null,
  method                text not null,
  notes                 text,
  operator_id           uuid references public.users (id) on delete set null,
  anchor_id             uuid references public.anchors (id) on delete set null,
  created_at            timestamptz not null default now()
);
comment on table public.working_copies is '2.0: forensic working copies, each linked to its original with how it was derived.';

alter table public.forensic_reports
  add column if not exists version integer not null default 1,
  add column if not exists supersedes_id uuid references public.forensic_reports (id) on delete restrict,
  add column if not exists analyst_name text,
  add column if not exists tool text,
  add column if not exists method text,
  add column if not exists anchor_id uuid references public.anchors (id) on delete set null;

-- A report is immutable once written; a correction is a new linked version.
drop trigger if exists append_only on public.forensic_reports;
create trigger append_only before update or delete on public.forensic_reports
  for each row execute function app.refuse_mutation();

-- ------------------------------------------------------------- F16 defence

create table if not exists public.access_requests (
  id               uuid primary key default gen_random_uuid(),
  case_id          uuid not null references public.cases (id) on delete cascade,
  requester_id     uuid not null references public.users (id) on delete cascade,
  reason           text not null,
  status           text not null default 'pending' check (status in ('pending', 'granted', 'refused', 'withdrawn')),
  decided_by       uuid references public.users (id) on delete set null,
  decision_reason  text,
  decided_at       timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
comment on table public.access_requests is '2.0: defence requests for access to a case, decided by the court. All logged.';
create index if not exists access_requests_case_idx on public.access_requests (case_id, created_at desc);

create table if not exists public.objections (
  id            uuid primary key default gen_random_uuid(),
  case_id       uuid not null references public.cases (id) on delete cascade,
  evidence_id   uuid references public.evidence_items (id) on delete set null,
  filed_by      uuid not null references public.users (id) on delete cascade,
  grounds       text not null,
  status        text not null default 'open' check (status in ('open', 'upheld', 'dismissed', 'withdrawn')),
  ruling        text,
  ruled_by      uuid references public.users (id) on delete set null,
  ruled_at      timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
comment on table public.objections is '2.0: objections to evidence, filed by defence, ruled on by the court.';

-- ------------------------------------------------------------- F17 court

create table if not exists public.court_events (
  id            uuid primary key default gen_random_uuid(),
  case_id       uuid not null references public.cases (id) on delete cascade,
  kind          text not null check (kind in ('hearing', 'order', 'adjournment', 'direction', 'judgment')),
  title         text not null,
  body          text,
  scheduled_for timestamptz,
  linked_type   text check (linked_type in ('evidence', 'summons', 'bail', 'objection', 'access_request')),
  linked_id     uuid,
  document_sha256 public.hash32,
  created_by    uuid references public.users (id) on delete set null,
  created_at    timestamptz not null default now()
);
comment on table public.court_events is '2.0: hearings, orders and directions, linked to the events they concern. Role-gated.';
create index if not exists court_events_case_idx on public.court_events (case_id, coalesce(scheduled_for, created_at));

create table if not exists public.summons_service_attempts (
  id            uuid primary key default gen_random_uuid(),
  summons_id    uuid not null references public.summons (id) on delete cascade,
  attempted_at  timestamptz not null default now(),
  method        text not null check (method in ('in_person', 'registered_post', 'email', 'sms', 'affixture', 'electronic')),
  outcome       text not null check (outcome in ('served', 'refused', 'not_found', 'address_wrong', 'deferred')),
  notes         text,
  recorded_by   uuid references public.users (id) on delete set null,
  created_at    timestamptz not null default now()
);
comment on table public.summons_service_attempts is '2.0: every attempt to serve a summons.';

alter table public.checkins add column if not exists accuracy_metres numeric(10, 2);
alter table public.violations
  add column if not exists severity text check (severity in ('minor', 'moderate', 'serious', 'critical')),
  add column if not exists court_finding text check (court_finding in ('no_violation', 'gps_drift', 'technical', 'violation', 'absconding'));

-- ------------------------------------------------------------- F18 accused

create table if not exists public.checkin_explanations (
  id             uuid primary key default gen_random_uuid(),
  bail_id        uuid not null references public.bail_conditions (id) on delete cascade,
  case_id        uuid not null references public.cases (id) on delete cascade,
  violation_id   uuid references public.violations (id) on delete set null,
  reason         text not null check (char_length(reason) between 5 and 2000),
  category       text not null check (category in ('medical', 'network', 'device', 'travel_permitted', 'other')),
  submitted_by   uuid not null references public.users (id) on delete cascade,
  submitted_at   timestamptz not null default now()
);
comment on table public.checkin_explanations is
  '2.0: the accused''s reason for a missed check-in, shown to the court beside it. Not a violation by itself.';

create table if not exists public.notification_outbox (
  id                 uuid primary key default gen_random_uuid(),
  recipient_user_id  uuid references public.users (id) on delete cascade,
  channel            text not null check (channel in ('email', 'sms', 'sandbox')),
  template           text not null,
  payload            jsonb not null default '{}'::jsonb,
  dedupe_key         text not null unique,
  status             text not null default 'queued' check (status in ('queued', 'sent', 'failed', 'skipped')),
  provider           text,
  error              text,
  created_at         timestamptz not null default now(),
  sent_at            timestamptz
);
comment on table public.notification_outbox is '2.0: reminders for summons and check-ins. Sandbox by default.';

-- ------------------------------------------------------------- F19 governance

create table if not exists public.approval_requests (
  id               uuid primary key default gen_random_uuid(),
  action           text not null check (action in ('case_close', 'evidence_destroy', 'custody_after_mismatch', 'legal_hold_release')),
  subject_type     text not null check (subject_type in ('case', 'evidence')),
  subject_id       uuid not null,
  case_id          uuid not null references public.cases (id) on delete restrict,
  requested_by     uuid not null references public.users (id) on delete restrict,
  requested_role   text not null,
  reason           text not null check (char_length(reason) >= 10),
  payload          jsonb not null default '{}'::jsonb,
  status           text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'executed', 'cancelled')),
  approver_id      uuid references public.users (id) on delete restrict,
  approver_role    text,
  approver_reason  text,
  decided_at       timestamptz,
  executed_at      timestamptz,
  idempotency_key  text unique,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  -- Two people, enforced where it cannot be forgotten.
  constraint approval_two_people check (approver_id is null or approver_id <> requested_by)
);
comment on table public.approval_requests is '2.0: two-person approval for critical actions. Requester and approver must differ.';
create index if not exists approvals_pending_idx on public.approval_requests (status, created_at) where status = 'pending';

create table if not exists public.legal_holds (
  id              uuid primary key default gen_random_uuid(),
  subject_type    text not null check (subject_type in ('case', 'evidence')),
  subject_id      uuid not null,
  case_id         uuid not null references public.cases (id) on delete restrict,
  reason          text not null,
  placed_by       uuid references public.users (id) on delete set null,
  placed_at       timestamptz not null default now(),
  released_by     uuid references public.users (id) on delete set null,
  release_reason  text,
  released_at     timestamptz,
  approval_id     uuid references public.approval_requests (id) on delete restrict
);
comment on table public.legal_holds is '2.0: a hold blocks disposal, deletion and destruction until released with a reason.';
create index if not exists legal_holds_active_idx on public.legal_holds (subject_type, subject_id) where released_at is null;

create table if not exists public.disposal_records (
  id            uuid primary key default gen_random_uuid(),
  evidence_id   uuid not null unique references public.evidence_items (id) on delete restrict,
  case_id       uuid not null references public.cases (id) on delete restrict,
  method        text not null check (method in ('returned_to_owner', 'destroyed', 'auctioned', 'transferred', 'retained_by_court')),
  performed_at  timestamptz not null default now(),
  witnesses     jsonb not null default '[]'::jsonb,
  notes         text,
  approval_id   uuid not null references public.approval_requests (id) on delete restrict,
  recorded_by   uuid references public.users (id) on delete set null,
  created_at    timestamptz not null default now()
);
comment on table public.disposal_records is '2.0: disposal at the end of a case. Requires an executed two-person approval.';

alter table public.evidence_items add column if not exists disposed_at timestamptz;

-- ------------------------------------------------------------- F4 alerts

create table if not exists public.discrepancy_alerts (
  id              uuid primary key default gen_random_uuid(),
  case_id         uuid references public.cases (id) on delete cascade,
  evidence_id     uuid references public.evidence_items (id) on delete cascade,
  kind            text not null check (kind in (
                    'MISSING_CONFIRMATION', 'DELAYED_TX', 'HASH_MISMATCH', 'INDEXER_LAG', 'SYNC_FAILED',
                    'SEAL_BROKEN', 'CUSTODY_GAP', 'RECORD_CHAIN_DISAGREE', 'SIGNATURE_INVALID', 'CLOCK_SKEW')),
  severity        text not null check (severity in ('info', 'warning', 'serious')),
  explanation     text not null,
  dedupe_key      text not null unique,
  status          text not null default 'open' check (status in ('open', 'acknowledged', 'resolved')),
  detected_at     timestamptz not null default now(),
  acknowledged_by uuid references public.users (id) on delete set null,
  acknowledged_at timestamptz,
  resolved_by     uuid references public.users (id) on delete set null,
  resolved_at     timestamptz,
  resolution      text,
  constraint resolution_has_reason check (status <> 'resolved' or (resolution is not null and char_length(resolution) >= 10))
);
comment on table public.discrepancy_alerts is '2.0: things that could not be verified. Alerts never penalise anyone automatically.';
create index if not exists alerts_open_idx on public.discrepancy_alerts (case_id, status, detected_at desc);

create table if not exists public.alert_comments (
  id          uuid primary key default gen_random_uuid(),
  alert_id    uuid not null references public.discrepancy_alerts (id) on delete cascade,
  author_id   uuid references public.users (id) on delete set null,
  author_role text,
  body        text not null check (char_length(body) between 1 and 4000),
  created_at  timestamptz not null default now()
);

-- ------------------------------------------------------------- F5 AI review

create table if not exists public.ai_reviews (
  id          uuid primary key default gen_random_uuid(),
  ai_flag_id  uuid not null references public.ai_flags (id) on delete cascade,
  case_id     uuid references public.cases (id) on delete cascade,
  reviewer_id uuid references public.users (id) on delete set null,
  reviewer_role text,
  decision    text not null check (decision in ('agree', 'contest', 'dismiss')),
  reason      text not null check (char_length(reason) >= 10),
  created_at  timestamptz not null default now()
);
comment on table public.ai_reviews is '2.0: a person''s recorded view of an AI output. AI never changes case status.';

-- ------------------------------------------------------------- comments for the validator

comment on table public.certificates is '2.0: every Section 63 certificate rendering, by digest.';
comment on table public.alert_comments is '2.0: discussion on a discrepancy alert.';

-- ------------------------------------------------------------- RLS, audit, timestamps

do $$
declare
  t text;
  case_tables text[] := array[
    'certificates', 'seizures', 'malkhana_movements', 'lab_intakes', 'working_copies', 'access_requests',
    'objections', 'court_events', 'checkin_explanations', 'approval_requests', 'legal_holds',
    'disposal_records', 'discrepancy_alerts', 'ai_reviews'];
  all_tables text[] := case_tables || array[
    'document_templates', 'seizure_items', 'summons_service_attempts', 'notification_outbox', 'alert_comments'];
begin
  foreach t in array all_tables loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke insert, update, delete on public.%I from anon, authenticated', t);
    execute format('drop trigger if exists audit_changes on public.%I', t);
    execute format('create trigger audit_changes after insert or update or delete on public.%I
                    for each row execute function app.audit_trigger()', t);
  end loop;

  -- Readable by roles assigned to the case, and by the registry.
  foreach t in array case_tables loop
    execute format('drop policy if exists %I on public.%I', t || '_case_read', t);
    execute format('create policy %I on public.%I for select to authenticated
                    using (app.has_role(array[''court_admin'']) or app.is_assigned(case_id))', t || '_case_read', t);
  end loop;
end $$;

-- Court events and objections are not for the accused's eyes through the API
-- path that bypasses the service; the API enforces the finer rules.

drop policy if exists document_templates_read on public.document_templates;
create policy document_templates_read on public.document_templates for select to authenticated using (true);

drop policy if exists seizure_items_read on public.seizure_items;
create policy seizure_items_read on public.seizure_items for select to authenticated
  using (exists (select 1 from public.seizures s where s.id = seizure_items.seizure_id
                 and (app.has_role(array['court_admin']) or app.is_assigned(s.case_id))));

drop policy if exists summons_attempts_read on public.summons_service_attempts;
create policy summons_attempts_read on public.summons_service_attempts for select to authenticated
  using (exists (select 1 from public.summons s where s.id = summons_service_attempts.summons_id
                 and (app.has_role(array['court_admin']) or app.is_assigned(s.case_id))));

drop policy if exists notification_outbox_own on public.notification_outbox;
create policy notification_outbox_own on public.notification_outbox for select to authenticated
  using (recipient_user_id = app.current_user_id() or app.has_role(array['court_admin']));

drop policy if exists alert_comments_read on public.alert_comments;
create policy alert_comments_read on public.alert_comments for select to authenticated
  using (exists (select 1 from public.discrepancy_alerts a where a.id = alert_comments.alert_id
                 and (app.has_role(array['court_admin']) or (a.case_id is not null and app.is_assigned(a.case_id)))));

do $$
declare t text;
begin
  foreach t in array array['document_templates', 'seizures', 'lab_intakes', 'access_requests', 'objections', 'approval_requests'] loop
    execute format('drop trigger if exists touch_updated_at on public.%I', t);
    execute format('create trigger touch_updated_at before update on public.%I for each row execute function app.touch_updated_at()', t);
  end loop;
end $$;

